package com.game_manager.gm.machine;import static com.game_manager.gm.machine.dto.MachineDtos.*;import com.game_manager.gm.common.error.ApplicationException;import com.game_manager.gm.gamingsession.*;import com.game_manager.gm.gamingsession.command.*;import com.game_manager.gm.machine.dto.StationLeaseDtos.SessionLeasePayload;import com.game_manager.gm.station.*;import java.time.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import tools.jackson.databind.ObjectMapper;
@Service public class StationLeaseService {private final MachinePrincipalProvider principal;private final GamingSessionRepository sessions;private final GamingStationProfileRepository stations;private final ApplicationProfileRepository profiles;private final StationHeartbeatRepository heartbeats;private final StationCommandRepository commands;private final StationPolicySigner signer;private final StationEnforcementProjectionService enforcement;private final ObjectMapper json;private final Clock clock;private final Duration duration,grace;
 public StationLeaseService(MachinePrincipalProvider principal,GamingSessionRepository sessions,GamingStationProfileRepository stations,ApplicationProfileRepository profiles,StationHeartbeatRepository heartbeats,StationCommandRepository commands,StationPolicySigner signer,StationEnforcementProjectionService enforcement,ObjectMapper json,Clock clock,@Value("${app.gaming-client.lease-duration-seconds:30}")long duration,@Value("${app.gaming-client.offline-grace-seconds:30}")long grace){this.principal=principal;this.sessions=sessions;this.stations=stations;this.profiles=profiles;this.heartbeats=heartbeats;this.commands=commands;this.signer=signer;this.enforcement=enforcement;this.json=json;this.clock=clock;this.duration=Duration.ofSeconds(duration);this.grace=Duration.ofSeconds(grace);}
 @Transactional public SignedSessionLease lease(){MachinePrincipal machine=principal.require();Instant now=clock.instant();GamingStationProfile station=stations.findByResourceId(machine.stationId()).orElseThrow(()->new ApplicationException(HttpStatus.NOT_FOUND,"Station not found"));long configVersion=station.getApplicationProfileId()==null?0:profiles.findById(station.getApplicationProfileId()).map(ApplicationProfile::getConfigurationVersion).orElse(0L);GamingSession session=sessions.findByResourceIdAndStatus(machine.stationId(),GamingSessionStatus.ACTIVE).orElse(null);boolean active=session!=null&&session.getEndsAt().isAfter(now);long cursor=Math.max(heartbeats.findById(machine.stationId()).map(StationHeartbeat::getLastCommandSequence).orElse(0L),session==null||session.getLastCommandSequence()==null?0L:session.getLastCommandSequence());Instant nominalExpiry=now.plus(duration);Instant expires=active&&session.getEndsAt().isBefore(nominalExpiry)?session.getEndsAt():nominalExpiry;Instant graceEnd=active&&session.getEndsAt().isBefore(expires.plus(grace))?session.getEndsAt():expires.plus(grace);UUID leaseId=UUID.randomUUID();SessionLeasePayload payload=new SessionLeasePayload(leaseId,machine.stationId(),active?session.getId():null,active?session.getCustomerId():null,active?session.getEndsAt():null,configVersion,now,expires,graceEnd,cursor,active?"ACTIVE":"LOCK");try{byte[] bytes=json.writeValueAsBytes(payload);enforcement.leaseIssued(machine,leaseId,payload.sessionId(),expires,configVersion,cursor);return new SignedSessionLease(Base64.getUrlEncoder().withoutPadding().encodeToString(bytes),"Ed25519",signer.keyId(),signer.sign(bytes));}catch(Exception e){if(e instanceof ApplicationException application)throw application;throw new ApplicationException(HttpStatus.INTERNAL_SERVER_ERROR,"Station lease could not be serialized");}}
 @Transactional public LockAckResponse lockAck(LockAckRequest request){MachinePrincipal machine=principal.require();StationCommand command=commands.findByStationIdAndSequence(machine.stationId(),request.commandSequence()).filter(value->value.getSessionId().equals(request.sessionId())&&(value.getCommandType()==StationCommandType.SESSION_TERMINATED||value.getCommandType()==StationCommandType.FORCE_LOCK)).orElseThrow(()->new ApplicationException(HttpStatus.CONFLICT,"Lock acknowledgement does not match a lock command"));Instant at=enforcement.lockAck(machine,request.sessionId(),request.commandSequence(),request.leaseId(),request.reason());if(command.getAcknowledgedAt()==null){command.setAcknowledgedAt(at);commands.save(command);}return new LockAckResponse(machine.stationId(),request.sessionId(),request.commandSequence(),at,StationEnforcementStatus.LOCKED.name());}
}
